from __future__ import annotations

import importlib
from abc import ABC, abstractmethod
from functools import lru_cache
from typing import Any, Optional
from uuid import UUID

from prefect.settings import get_current_settings

#: The import path of this interface package. Pointing the cleanup queue storage
#: setting at this module is a configuration error -- a concrete implementation
#: module must be supplied instead.
INTERFACE_MODULE = "prefect.server.worker_communication.cleanup_queue"


class WorkerCleanupQueue(ABC):
    """
    Abstract contract for a reliable worker cleanup queue.

    Implementations provide idempotent enqueue, lease-based reservation,
    acknowledgment, release, renewal, expiry, dead-lettering, and wakeup
    notification for cleanup messages delivered to workers.
    """

    @abstractmethod
    def clear(self) -> None:
        """Reset all internal queue state."""

    @abstractmethod
    def enqueue(
        self,
        message_id: UUID,
        idempotency_key: str,
        work_pool_id: UUID,
        kind: Any,
        target: dict[str, Any],
        data: Optional[dict[str, Any]] = None,
        work_queue_id: Optional[UUID] = None,
    ) -> Any:
        """Enqueue a cleanup message (idempotent)."""

    @abstractmethod
    def reserve(
        self,
        work_pool_id: UUID,
        preferred_work_queue_ids: Optional[list[UUID]] = None,
        cleanup_kinds: Optional[list[Any]] = None,
    ) -> Any:
        """Reserve the next available message for a work pool."""

    @abstractmethod
    def ack(
        self, work_pool_id: UUID, message_id: UUID, reservation_token: str
    ) -> Any:
        """Acknowledge successful processing of a reserved message."""

    @abstractmethod
    def release(
        self,
        work_pool_id: UUID,
        message_id: UUID,
        reservation_token: str,
        reason: str,
    ) -> Any:
        """Release a reserved message for redelivery or dead-lettering."""

    @abstractmethod
    def renew(
        self, work_pool_id: UUID, message_id: UUID, reservation_token: str
    ) -> Any:
        """Extend the lease of an active reservation."""

    @abstractmethod
    def read_message(self, work_pool_id: UUID, message_id: UUID) -> Any:
        """Return the stored message for a work pool, if present."""

    @abstractmethod
    def read_dead_letter(self, work_pool_id: UUID, message_id: UUID) -> Any:
        """Return the dead-letter entry for a work pool, if present."""

    @abstractmethod
    def read_wakeup_sequence(self, work_pool_id: UUID) -> int:
        """Return the current wakeup sequence counter for a work pool."""

    @abstractmethod
    async def wait_for_wakeup(
        self,
        work_pool_id: UUID,
        after: Optional[int] = None,
        timeout: Optional[float] = None,
    ) -> Any:
        """Wait until the wakeup sequence for a work pool advances."""

    @abstractmethod
    def expire_leases(
        self, work_pool_id: Optional[UUID] = None, limit: Optional[int] = None
    ) -> Any:
        """Expire overdue leases, redelivering or dead-lettering messages."""


