def _load_worker_cleanup_queue(storage: str) -> WorkerCleanupQueue:
    module = importlib.import_module(storage)
    queue_cls = getattr(module, "WorkerCleanupQueue")
    return queue_cls()


def get_worker_cleanup_queue() -> WorkerCleanupQueue:
    """
    Load and return the configured :class:`WorkerCleanupQueue` implementation.

    The backing module is selected via
    ``PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE``. The returned
    instance is cached per storage path so that queue state is shared across
    callers.

    Raises:
        ValueError: if the configured module is this interface package itself
            rather than a concrete implementation.
    """
    storage = get_current_settings().server.worker_channel.cleanup_queue_storage

    if storage == INTERFACE_MODULE:
        raise ValueError(
            "`PREFECT_SERVER_WORKER_CHANNEL_CLEANUP_QUEUE_STORAGE` must point to a "
            "concrete WorkerCleanupQueue implementation module, not the interface "
            f"package {INTERFACE_MODULE!r}."
        )

    return _load_worker_cleanup_queue(storage)


